import { Employee } from "../types";
import { getShiftTimesAs, restHoursForDailyRepeatingShift, LEGACY_BASELINE_DATE } from "../shift-templates";
import { buildStaggeredOffDays } from "../roster-generation";
import { deriveTeamRotation, DemandDay, RotationInfeasibleError } from "../rotation-feasibility";
import { getCompanyRequiredAgents } from "../company-config";
import { resolveDefaultLaborRules } from "../labor-rules";
import { smallDemoCompanyOperatingDays } from "./flights";

/**
 * SMALL DEMO DATASET — workforce side.
 *
 * ~22 NAMED, STABLE employees (never regenerated by index/name-pool, the
 * same approach lib/seed-data.ts uses for its 8 protected scripted
 * employees) so the same person is recognizable by name across Monthly
 * Planning and Live Operations every time this dataset is reset. This is
 * deliberately small and hand-authored, not a scaled-down call into
 * lib/employee-generator.ts's ~200-employee generator — a hand-picked
 * roster is what makes "stable, recognizable names" and "deliberately
 * tight headcount" both true at once.
 *
 * Sized against lib/demo-small/flights.ts's real demand, not in the
 * abstract — see the per-group comments below for the arithmetic. The
 * target is a plan that is NORMALLY FEASIBLE (most requirements get a
 * valid, fully-shift-contained assignment) but with little slack: a few
 * shift-code choices deliberately leave a role under-covered or a
 * candidate only "flagged" (would need an early call-in/extension), so
 * the demo has real, honest bottlenecks to click through — never
 * engineered to guarantee 100% coverage.
 */

const ALL_DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
const LABOR_RULES = resolveDefaultLaborRules();
const restBeforeShiftFor = (code: string) => restHoursForDailyRepeatingShift(code, LEGACY_BASELINE_DATE);

function buildEmployee(partial: {
  id: string;
  name: string;
  skills: string[];
  assignment: string;
  shift_code: string;
  weekly_hours: number;
  off_days: string[];
  is_duty_officer?: boolean;
  foreign_company_authorizations?: string[];
}): Omit<Employee, "weekly_shifts"> {
  const { shift_start, shift_end } = getShiftTimesAs(partial.shift_code, LEGACY_BASELINE_DATE);
  return {
    id: partial.id,
    name: partial.name,
    skills: partial.skills,
    assignment: partial.assignment,
    shift_code: partial.shift_code,
    shift_start,
    shift_end,
    rest_before_shift_hours: restBeforeShiftFor(partial.shift_code),
    weekly_hours: partial.weekly_hours,
    is_duty_officer: partial.is_duty_officer ?? false,
    off_days: partial.off_days,
    foreign_company_authorizations: partial.foreign_company_authorizations ?? [],
    active: true,
  };
}

