/** Builds the 16 flat-rule (non-fixed-cycle, non-foreign) employees above, each staggered 2 OFF days/week, Wednesday kept working (matches the main dataset's convention for any skill a live requirement queries directly). */
function buildFlatRuleEmployees(
  specs: { id: string; name: string; skills: string[]; shift_code: string; weekly_hours: number }[],
  assignment: string
): Omit<Employee, "weekly_shifts">[] {
  const candidatePool = ALL_DAYS.filter((d) => d !== "Wednesday");
  return specs.map((spec, n) =>
    buildEmployee({
      ...spec,
      assignment,
      off_days: buildStaggeredOffDays(n, LABOR_RULES.normalWeeklyOffDays, candidatePool),
    })
  );
}

/**
 * Qatar Airways (3) — the small demo's one foreign-company group. Real
 * demand: 2 agents/flight, Mon/Wed/Fri only (see flights.ts). Headcount
 * derived through the SAME generic Rotation Feasibility Engine the main
 * dataset's foreign-company groups use (lib/rotation-feasibility.ts), off
 * their REAL flight days here — never hand-picked off-days, and never a
 * silently-invented fallback if infeasible (throws RotationInfeasibleError,
 * exactly like lib/employee-generator.ts).
 */
function buildQatarAirwaysGroup(): Omit<Employee, "weekly_shifts">[] {
  const assignment = "Qatar Airways";
  const flightDays = smallDemoCompanyOperatingDays(assignment);
  const requiredAgents = getCompanyRequiredAgents(assignment);
  if (requiredAgents === undefined) {
    throw new Error(`"${assignment}" has no confirmed company_config headcount — lib/company-config.ts must define it before the small demo can roster this group.`);
  }
  const demand: DemandDay[] = ALL_DAYS.map((d) => ({ dayOfWeek: d, requiredAgents: flightDays.includes(d) ? requiredAgents : 0 }));

  const count = 3;
  const result = deriveTeamRotation(count, demand, ALL_DAYS, LABOR_RULES.normalWeeklyOffDays, undefined, 4, LABOR_RULES.maxConsecutiveOffDays);
  if (!result.feasible || !result.candidate) {
    throw new RotationInfeasibleError(assignment, count, demand, result.reason ?? "No feasible rotation found.", LABOR_RULES.normalWeeklyOffDays);
  }

  const offDaysByMember: string[][] = [];
  for (const group of result.candidate.groups) {
    for (let k = 0; k < group.size; k++) offDaysByMember.push(group.offDays);
  }

  const names = [
    { id: "small-nawal-fassi", name: "Nawal Fassi" },
    { id: "small-yassine-rifai", name: "Yassine Rifai" },
    { id: "small-btissam-guessous", name: "Btissam Guessous" },
  ];

  return names.map((n, i) =>
    buildEmployee({
      id: n.id,
      name: n.name,
      skills: ["Boarding"],
      assignment,
      shift_code: "NR01",
      weekly_hours: 24,
      off_days: offDaysByMember[i],
      foreign_company_authorizations: [assignment],
    })
  );
}

/**
 * One Duty Officer and one Transit agent — small (1 each), purely to keep
 * both FIXED_PLANNING_TEAMS exclusions (lib/teams.ts) exercisable in the
 * UI (never offered as ordinary candidates) without allocating headcount
 * this dataset's actual flight demand doesn't call for. Both use the same
 * confirmed JR->NT->OFF->OFF cycle as the main dataset
 * (lib/fixed-cycle-rotation.ts).
 */
import { JR_NT_OFF_OFF_CYCLE, buildFixedCycleWeeklySchedule, offDaysForDisplayedWeek, FixedCycleDefinition } from "../fixed-cycle-rotation";

export interface SmallDemoFixedCycleSeed {
  employee: Omit<Employee, "weekly_shifts">;
  cycle: FixedCycleDefinition;
  cycleOffset: number;
}

function buildFixedCycleEmployee(id: string, name: string, skills: string[], assignment: string, cycleOffset: number): SmallDemoFixedCycleSeed {
  const cycle = JR_NT_OFF_OFF_CYCLE;
  const off_days = offDaysForDisplayedWeek(cycle, cycleOffset, ALL_DAYS);
  const referenceStep = cycle.steps.find((s) => "code" in s) as { code: string } | undefined;
  const referenceCode = referenceStep?.code ?? null;
  const { shift_start, shift_end } = referenceCode ? getShiftTimesAs(referenceCode, LEGACY_BASELINE_DATE) : { shift_start: null, shift_end: null };
  return {
    employee: {
      id,
      name,
      skills,
      assignment,
      shift_code: referenceCode,
      shift_start,
      shift_end,
      rest_before_shift_hours: referenceCode ? restBeforeShiftFor(referenceCode) : 0,
      weekly_hours: 30,
      is_duty_officer: assignment === "Duty Officers",
      off_days,
      foreign_company_authorizations: [],
      active: true,
    },
    cycle,
    cycleOffset,
  };
}

export const SMALL_DEMO_FIXED_CYCLE_EMPLOYEES: SmallDemoFixedCycleSeed[] = [
  buildFixedCycleEmployee("small-nabil-cherkaoui", "Nabil Cherkaoui", ["Boarding"], "Duty Officers", 0),
  buildFixedCycleEmployee("small-aziz-lahlou", "Aziz Lahlou", ["Transit"], "Transit", 2),
];

/**
 * A rotating-shift example (1) — same demonstrative purpose as the main
 * dataset's Amine Sqalli: concrete, non-uniform day-to-day shift-code
 * variety (MT01 most days, AP01 Saturday) for one General T1 Pool
 * employee, with the confirmed flat 2-OFF-days rule (Thursday, Sunday).
 */
const ROTATING_PATTERN: { day: string; code: string | null }[] = [
  { day: "Monday", code: "MT01" },
  { day: "Tuesday", code: "MT01" },
  { day: "Wednesday", code: "MT01" },
  { day: "Thursday", code: "OFF" },
  { day: "Friday", code: "MT01" },
  { day: "Saturday", code: "AP01" },
  { day: "Sunday", code: "OFF" },
];

function buildRotatingEmployee(): { employee: Omit<Employee, "weekly_shifts">; pattern: typeof ROTATING_PATTERN } {
  return {
    employee: buildEmployee({
      id: "small-mounir-skalli",
      name: "Mounir Skalli",
      skills: ["Gate"],
      assignment: "General T1 Pool",
      shift_code: "MT01",
      weekly_hours: 24,
      off_days: ["Thursday", "Sunday"],
    }),
    pattern: ROTATING_PATTERN,
  };
}

export const SMALL_DEMO_ROTATING_EMPLOYEE = buildRotatingEmployee();

/**
 * Flat-rule employees (General T1 Pool + Profiling + Mesure) — 16 total,
 * built once here so dataset.ts can assemble weekly_shifts for all of
 * them identically (buildUniformWeeklySchedule), same as the main
 * dataset's generated pool.
 */
export const SMALL_DEMO_FLAT_RULE_EMPLOYEES: Omit<Employee, "weekly_shifts">[] = [
  ...buildFlatRuleEmployees(GENERAL_T1_POOL, "General T1 Pool"),
  ...buildFlatRuleEmployees(PROFILING, "Profiling"),
  ...buildFlatRuleEmployees(MESURE, "Mesure"),
];

export const SMALL_DEMO_QATAR_AIRWAYS_EMPLOYEES: Omit<Employee, "weekly_shifts">[] = buildQatarAirwaysGroup();

// 10 General T1 Pool + 2 Profiling + 4 Mesure + 3 Qatar Airways + 1 Duty
// Officer + 1 Transit + 1 rotating-shift example = 22 employees total.
export const SMALL_DEMO_EMPLOYEE_COUNT =
  SMALL_DEMO_FLAT_RULE_EMPLOYEES.length + SMALL_DEMO_QATAR_AIRWAYS_EMPLOYEES.length + SMALL_DEMO_FIXED_CYCLE_EMPLOYEES.length + 1;
